import {Ring} from './model.js';
const $=id=>document.getElementById(id);let q=new Ring(8),next=1,running=false,timers=[],trace=[];
function record(op,value){trace.unshift({operation:op,value,head:q.head,tail:q.tail,count:q.count,time:new Date().toISOString()});trace=trace.slice(0,200);$('status').textContent=op==='PUSH'?`Published message ${value}.`:op==='POP'?`Consumed message ${value}.`:op==='FULL'?'Queue full. Message was not published.':'Queue empty. Nothing to consume.';render();}
function push(){const v=next;if(q.push(v)){next++;record('PUSH',v);}else record('FULL',v);}
function pop(){const v=q.pop();record(v===null?'EMPTY':'POP',v);}
function stop(){timers.forEach(clearInterval);timers=[];running=false;$('play').textContent='Start experiment';}
function start(){stop();running=true;$('play').textContent='Pause experiment';for(const [id,fn] of [['producer',push],['consumer',pop]]){const rate=Number($(id).value);if(rate)timers.push(setInterval(fn,1000/rate));}}
function reset(){stop();q=new Ring(Number($('capacity').value));next=1;trace=[];$('status').textContent='Queue reset. Ready for a new experiment.';render();}
function render(){$('occupancy').textContent=`${q.count} / ${q.capacity}`;$('transferred').textContent=q.popped;$('blocked').textContent=q.blocked;$('head').textContent=q.head;$('tail').textContent=q.tail;$('queue-state').textContent=q.count===q.capacity?'FULL':q.count?'ACTIVE':'EMPTY';$('fifo').textContent=q.count?Array.from({length:q.count},(_,i)=>q.slots[(q.tail+i)%q.capacity]).join(' → '):'Empty';$('ring').innerHTML=q.slots.map((v,i)=>`<div class="slot ${v!==null?'occupied':''}"><small>SLOT ${i.toString().padStart(2,'0')}</small><strong>${v===null?'—':v}</strong><span class="pointers">${q.head===i?'H':''}${q.tail===i?'T':''}</span></div>`).join('');$('trace').innerHTML=trace.length?trace.slice(0,30).map(r=>`<div class="trace-row"><span>${r.operation}</span><span>${r.value===null?'No message':'Message '+r.value}</span><small>${r.count} occupied</small></div>`).join(''):'<p class="hint">Your next operation appears here.</p>';$('export').disabled=!trace.length;}
$('play').onclick=()=>running?stop():start();$('push').onclick=push;$('pop').onclick=pop;$('reset').onclick=reset;$('capacity').onchange=reset;
for(const [id,out] of [['producer','p-out'],['consumer','c-out']])$(id).oninput=()=>{$(out).value=$(id).value;if(running)start();};
function download(data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ringlab-trace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>download({model:'Sequential browser model; not a concurrency benchmark',capacity:q.capacity,trace:[...trace].reverse()});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function benchmark(d){for(const k of ['messages','rounds','capacity','spsc_per_second','mutex_per_second'])if(!Number.isFinite(d[k])||d[k]<=0)throw Error('Invalid benchmark: positive numeric '+k+' required.');$('benchmark').innerHTML=`<div class="bench-grid"><div><strong>${(d.spsc_per_second/1e6).toFixed(2)} M/s</strong><span>SPSC queue</span></div><div><strong>${(d.mutex_per_second/1e6).toFixed(2)} M/s</strong><span>Mutex queue</span></div><div><strong>${(d.spsc_per_second/d.mutex_per_second).toFixed(2)}×</strong><span>Measured throughput ratio</span></div></div><p class="hint">${d.messages.toLocaleString()} messages · ${d.rounds} rounds · ${d.capacity} slots<br>${esc(d.environment||'Environment not provided')} · Compiler ${esc(d.compiler||'not provided')}</p>`;}
$('benchmark-file').onchange=async()=>{try{const f=$('benchmark-file').files[0];if(!f)return;if(f.size>50000)throw Error('Choose a JSON report smaller than 50 KB.');benchmark(JSON.parse(await f.text()));$('benchmark-error').textContent='Showing your imported benchmark.';}catch(e){$('benchmark-error').textContent=e.message;}finally{$('benchmark-file').value='';}};
fetch('./benchmark.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(benchmark).catch(()=>$('benchmark').textContent='Recorded benchmark unavailable. Import a report from the native executable.');render();
